import React from 'react'

export default function Matches() {
    return (
        <div>
            <h1 className="text-2xl font-bold text-gray-800">📅 Matches</h1>
            <p className="text-gray-500 mt-2">Live and upcoming matches will appear here</p>
            <div className="mt-6 bg-white rounded-xl shadow-md p-6 text-center text-gray-400">
                Coming soon: Real match data with AI predictions!
            </div>
        </div>
    )
}
